:root {
  --ink: #07080c;
  --ink-2: #0c0e15;
  --ink-3: #12151f;
  --bone: #d9d1bd;
  --bone-dim: #9a9486;
  --gold: #c9a35c;
  --gold-bright: #f0d28e;
  --blood: #8e2b2b;
  --blood-bright: #d04444;
  --cyan: #77d9d2;
  --violet: #a68bff;
  --panel: rgba(10, 12, 18, .86);
  --line: rgba(201, 163, 92, .3);
  --line-soft: rgba(201, 163, 92, .14);
  --common: #c9c4b8;
  --magic: #6ea8ff;
  --rare: #f2cf66;
  --legendary: #ff9a3c;
  --font-display: Georgia, "Palatino Linotype", "Book Antiqua", serif;
  --font-ui: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --font-mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--font-ui);
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

button { font: inherit; color: inherit; }

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #08090d;
  touch-action: none;
}

.hidden { display: none !important; }

/* ---------- shared chrome ---------- */

.panel {
  background:
    linear-gradient(180deg, rgba(28, 24, 22, .92), rgba(9, 10, 15, .92));
  border: 1px solid var(--line);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .45), inset 0 0 30px rgba(201, 163, 92, .045);
  border-radius: 3px;
  position: relative;
}
.panel::before, .panel::after {
  content: "";
  position: absolute;
  width: 7px;
  height: 7px;
  border: 1px solid var(--gold);
  opacity: .55;
  pointer-events: none;
}
.panel::before { top: -3px; left: -3px; border-right: 0; border-bottom: 0; }
.panel::after { bottom: -3px; right: -3px; border-left: 0; border-top: 0; }

.eyebrow {
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: .28em;
  text-transform: uppercase;
  color: var(--gold);
  opacity: .82;
}

h1, h2, h3 { font-family: var(--font-display); font-weight: 600; margin: 0; }

kbd {
  display: inline-block;
  min-width: 22px;
  padding: 2px 6px;
  border: 1px solid rgba(217, 209, 189, .28);
  border-bottom-color: rgba(217, 209, 189, .5);
  border-radius: 3px;
  background: rgba(255, 255, 255, .04);
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--bone);
  text-align: center;
}

.btn {
  appearance: none;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(52, 43, 35, .8), rgba(18, 18, 24, .9));
  color: var(--bone);
  padding: 10px 18px;
  border-radius: 2px;
  cursor: pointer;
  letter-spacing: .14em;
  text-transform: uppercase;
  font-size: 11px;
  font-weight: 600;
  transition: border-color .16s ease, background .16s ease, color .16s ease, transform .12s ease;
  position: relative;
}
.btn:hover { border-color: rgba(240, 210, 142, .7); color: var(--gold-bright); background: linear-gradient(180deg, rgba(70, 55, 38, .9), rgba(24, 22, 26, .95)); }
.btn:active { transform: translateY(1px); }
.btn.primary {
  border-color: rgba(201, 163, 92, .65);
  background: linear-gradient(180deg, #6f4a25, #372313 55%, #1c120c);
  color: #f7e6bf;
  box-shadow: 0 0 24px rgba(201, 163, 92, .16), inset 0 1px 0 rgba(255, 232, 186, .22);
}
.btn.primary:hover { border-color: var(--gold-bright); box-shadow: 0 0 34px rgba(201, 163, 92, .28), inset 0 1px 0 rgba(255, 232, 186, .3); }
.btn.ghost { background: rgba(255, 255, 255, .02); }
.btn.small { padding: 8px 12px; font-size: 10px; }
.btn.big { padding: 16px 54px; font-size: 13px; letter-spacing: .26em; }
.btn:disabled { opacity: .4; cursor: not-allowed; filter: grayscale(.6); }
.btn:focus-visible, .icon-btn:focus-visible, .equip-slot:focus-visible, .item-cell:focus-visible, .card:focus-visible {
  outline: 2px solid var(--gold-bright);
  outline-offset: 2px;
}

.close-btn {
  width: 34px; height: 34px;
  border: 1px solid var(--line-soft);
  background: transparent;
  color: var(--bone-dim);
  cursor: pointer;
  border-radius: 2px;
  font-size: 14px;
}
.close-btn:hover { color: var(--gold-bright); border-color: var(--line); }

.coin, .skull {
  display: inline-block;
  width: 11px; height: 11px;
  border-radius: 50%;
  position: relative;
  flex: none;
}
.coin { background: radial-gradient(circle at 35% 30%, #ffe6a4, #c79335 55%, #6e4a13); box-shadow: 0 0 7px rgba(240, 210, 142, .5); }
.skull { background: radial-gradient(circle at 40% 32%, #e7dfcc, #8f897b 60%, #4f4c44); border-radius: 45% 45% 40% 40%; }
.skull::before, .skull::after { content: ""; position: absolute; top: 3px; width: 2px; height: 3px; border-radius: 50%; background: #1a1713; }
.skull::before { left: 2px; } .skull::after { right: 2px; }

/* ---------- HUD ---------- */

#hud { position: absolute; inset: 0; pointer-events: none; z-index: 5; }

.hud-top {
  position: absolute;
  top: 0; left: 0; right: 0;
  padding: max(14px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) 0 max(16px, env(safe-area-inset-left));
  display: grid;
  grid-template-columns: minmax(230px, 1fr) auto minmax(230px, 1fr);
  align-items: start;
  gap: 14px;
}

.hud-left { padding: 9px 12px 8px; width: min(330px, 100%); }
.level-row { display: flex; align-items: center; gap: 10px; }
.level-badge {
  width: 38px; height: 38px;
  flex: none;
  display: grid; place-items: center;
  border: 1px solid rgba(201, 163, 92, .55);
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #3c2c1d, #120f0d 72%);
  color: var(--gold-bright);
  font-family: var(--font-display);
  font-size: 17px;
  box-shadow: inset 0 0 12px rgba(201, 163, 92, .14), 0 0 14px rgba(0, 0, 0, .4);
}
.bars { flex: 1; display: flex; flex-direction: column; gap: 5px; }
.bar {
  position: relative;
  height: 13px;
  background: rgba(0, 0, 0, .55);
  border: 1px solid rgba(217, 209, 189, .13);
  border-radius: 2px;
  overflow: hidden;
}
.bar i {
  position: absolute; inset: 0 auto 0 0;
  width: 100%;
  transition: width .18s ease;
}
.bar.hp i { background: linear-gradient(90deg, #5a1414, #a72f2f 60%, #d4554b); box-shadow: 0 0 12px rgba(212, 85, 75, .35); }
.bar.xp { height: 9px; }
.bar.xp i { background: linear-gradient(90deg, #1c5d63, #4fb7b0 70%, #8be5d9); box-shadow: 0 0 12px rgba(79, 183, 176, .3); }
.bar span {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: .05em;
  color: rgba(255, 248, 230, .88);
  text-shadow: 0 1px 2px #000;
}
.hud-stats {
  display: flex; gap: 12px;
  margin-top: 6px; padding-left: 48px;
  font-family: var(--font-mono);
  font-size: 9px; letter-spacing: .1em;
  color: var(--bone-dim);
}
.hud-stats span { white-space: nowrap; }

.hud-center { text-align: center; padding-top: 2px; min-width: 150px; }
.timer {
  font-family: var(--font-display);
  font-size: clamp(26px, 3.4vw, 38px);
  line-height: 1;
  color: #f1e6ce;
  letter-spacing: .08em;
  text-shadow: 0 2px 0 #000, 0 0 24px rgba(201, 163, 92, .25);
  font-variant-numeric: tabular-nums;
}
.wave-label {
  margin-top: 3px;
  font-family: var(--font-display);
  font-size: 10px; letter-spacing: .22em; text-transform: uppercase;
  color: var(--bone-dim);
  text-shadow: 0 1px 2px #000;
}
.boss-bar { margin: 9px auto 0; width: min(380px, 60vw); }
.boss-name {
  display: flex; justify-content: space-between;
  font-family: var(--font-display);
  font-size: 10px; letter-spacing: .2em;
  color: #e2a6a6;
  text-shadow: 0 1px 3px #000;
  margin-bottom: 3px;
}
.boss-track { height: 7px; background: rgba(0, 0, 0, .65); border: 1px solid rgba(212, 85, 75, .35); border-radius: 2px; overflow: hidden; }
.boss-track i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #4d0f0f, #b42d2d 65%, #f0674d); box-shadow: 0 0 12px rgba(240, 103, 77, .5); transition: width .2s linear; }

.hud-right { justify-self: end; display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.currency {
  display: flex; align-items: center; gap: 7px;
  padding: 7px 11px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--gold-bright);
}
.currency .skull { margin-left: 7px; }
.currency b { font-weight: 600; min-width: 18px; text-align: left; }
.hud-buttons { display: flex; gap: 6px; pointer-events: auto; }
.icon-btn {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  background: linear-gradient(180deg, rgba(28, 25, 23, .9), rgba(9, 10, 14, .92));
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  cursor: pointer;
  color: var(--bone-dim);
  transition: color .15s, border-color .15s;
}
.icon-btn:hover { color: var(--gold-bright); border-color: var(--line); }
.icon-btn svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
#pauseBtn svg { fill: currentColor; stroke: none; }
.mute-slash { display: none; }
.muted .mute-wave { display: none; }
.muted .mute-slash { display: block; }

.equip-dock {
  position: absolute;
  left: max(16px, env(safe-area-inset-left));
  bottom: max(16px, env(safe-area-inset-bottom));
  display: flex; gap: 7px;
  pointer-events: auto;
}
.equip-slot {
  width: 56px; height: 56px;
  border: 1px solid var(--line-soft);
  background: linear-gradient(180deg, rgba(23, 22, 26, .9), rgba(8, 9, 13, .92));
  border-radius: 2px;
  display: grid; place-items: center;
  position: relative;
  cursor: pointer;
  padding: 0;
  transition: border-color .15s, transform .12s;
}
.equip-slot:hover { border-color: var(--line); transform: translateY(-2px); }
.equip-slot .slot-glyph { width: 30px; height: 30px; opacity: .26; }
.equip-slot .item-icon { width: 42px; height: 42px; }
.equip-slot .slot-key {
  position: absolute; right: 3px; bottom: 2px;
  font-family: var(--font-mono); font-size: 8px; color: var(--bone-dim); opacity: .7;
}

.hint {
  position: absolute;
  left: 50%; bottom: max(20px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  font-family: var(--font-display);
  font-size: 10px; letter-spacing: .18em; text-transform: uppercase;
  color: rgba(217, 209, 189, .52);
  text-shadow: 0 1px 3px #000;
  white-space: nowrap;
  transition: opacity .6s ease;
  pointer-events: none;
}
.hint.fade { opacity: 0; }

.toasts {
  position: absolute;
  left: 50%; bottom: max(58px, calc(env(safe-area-inset-bottom) + 50px));
  transform: translateX(-50%);
  display: flex; flex-direction: column-reverse; align-items: center; gap: 6px;
  width: min(92vw, 460px);
  pointer-events: none;
}
.toast {
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: .08em;
  padding: 6px 14px;
  background: rgba(8, 9, 13, .88);
  border: 1px solid var(--line-soft);
  border-left: 2px solid var(--common);
  color: var(--bone);
  border-radius: 2px;
  animation: toast-in .22s ease-out;
  text-align: center;
  max-width: 100%;
  box-shadow: 0 6px 20px rgba(0, 0, 0, .45);
}
.toast.rare { border-left-color: var(--rare); color: #f6e2a9; }
.toast.magic { border-left-color: var(--magic); color: #c6dcff; }
.toast.legendary { border-left-color: var(--legendary); color: #ffd2a3; box-shadow: 0 0 20px rgba(255, 154, 60, .2); }
.toast.gold { border-left-color: var(--gold); color: var(--gold-bright); }
.toast.bad { border-left-color: var(--blood-bright); color: #ffc3c3; }
@keyframes toast-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

.joystick {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  bottom: max(26px, calc(env(safe-area-inset-bottom) + 14px));
  pointer-events: none;
}
.stick-base {
  width: 118px; height: 118px;
  border-radius: 50%;
  border: 1px solid rgba(201, 163, 92, .28);
  background: radial-gradient(circle, rgba(201, 163, 92, .08), rgba(5, 6, 10, .3) 70%);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, .5);
  display: grid; place-items: center;
}
.stick-knob {
  width: 50px; height: 50px;
  border-radius: 50%;
  border: 1px solid rgba(240, 210, 142, .45);
  background: radial-gradient(circle at 40% 35%, rgba(201, 163, 92, .5), rgba(40, 30, 22, .8) 70%);
  box-shadow: 0 0 16px rgba(201, 163, 92, .2);
  transform: translate(0, 0);
}

/* ---------- screens & overlays ---------- */

.screen { position: absolute; inset: 0; z-index: 10; display: grid; place-items: center; }
#menu {
  background:
    radial-gradient(ellipse at 50% 46%, rgba(26, 20, 20, .18), rgba(4, 5, 8, .82) 68%),
    linear-gradient(180deg, rgba(4, 5, 8, .35), rgba(4, 5, 8, .9));
}
.menu-vignette {
  position: absolute; inset: 0;
  background: radial-gradient(circle at 50% 42%, transparent 20%, rgba(0, 0, 0, .68) 82%);
  pointer-events: none;
}
.menu-inner {
  position: relative;
  text-align: center;
  padding: 28px;
  width: min(760px, 94vw);
  animation: rise .7s cubic-bezier(.2, .7, .2, 1) both;
}
@keyframes rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.logo {
  margin: 10px 0 0;
  font-size: clamp(54px, 10vw, 104px);
  line-height: .92;
  letter-spacing: .06em;
  color: #e8d9b9;
  text-shadow: 0 0 40px rgba(201, 163, 92, .2), 0 5px 0 rgba(0, 0, 0, .55);
}
.logo span { color: #8f2f2f; text-shadow: 0 0 34px rgba(180, 48, 48, .4), 0 4px 0 #000; }
.logo-rule { display: flex; align-items: center; justify-content: center; gap: 12px; margin: 14px auto 12px; width: min(340px, 70%); }
.logo-rule i { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(201, 163, 92, .65)); }
.logo-rule i:last-child { background: linear-gradient(90deg, rgba(201, 163, 92, .65), transparent); }
.logo-rule b { color: var(--gold); font-size: 12px; font-weight: 400; }
.tagline { margin: 0 0 24px; font-family: var(--font-display); font-style: italic; color: var(--bone-dim); font-size: clamp(13px, 1.5vw, 16px); letter-spacing: .04em; }
.menu-controls { display: flex; justify-content: center; flex-wrap: wrap; gap: 18px; margin: 20px 0 22px; color: var(--bone-dim); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; }
.menu-controls span { display: flex; align-items: center; gap: 6px; }
.menu-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line-soft); border: 1px solid var(--line-soft); margin: 0 auto; width: min(600px, 100%); }
.menu-features div { background: rgba(7, 8, 12, .72); padding: 12px 10px; }
.menu-features b { display: block; font-family: var(--font-display); font-size: 11px; letter-spacing: .18em; text-transform: uppercase; color: var(--gold); font-weight: 500; margin-bottom: 4px; }
.menu-features span { font-size: 10px; color: var(--bone-dim); }
.best { margin-top: 16px; font-family: var(--font-mono); font-size: 10px; letter-spacing: .1em; color: var(--gold); opacity: .8; }
.menu-footer { position: absolute; bottom: max(16px, env(safe-area-inset-bottom)); left: 0; right: 0; text-align: center; font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: rgba(217, 209, 189, .34); padding: 0 16px; }

.overlay {
  position: absolute; inset: 0; z-index: 20;
  display: flex; align-items: center; justify-content: center;
  padding: max(16px, env(safe-area-inset-top)) 16px max(16px, env(safe-area-inset-bottom));
  background: radial-gradient(ellipse at 50% 45%, rgba(14, 13, 18, .72), rgba(3, 4, 7, .9));
  backdrop-filter: blur(3px);
  animation: overlay-in .18s ease-out;
  overflow-y: auto;
}
@keyframes overlay-in { from { opacity: 0; } to { opacity: 1; } }
.overlay-panel {
  position: relative;
  width: min(860px, 100%);
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  padding: clamp(20px, 3vw, 34px);
  background:
    linear-gradient(180deg, rgba(24, 21, 22, .97), rgba(8, 9, 13, .98)),
    repeating-linear-gradient(45deg, rgba(255, 255, 255, .012) 0 2px, transparent 2px 6px);
  border: 1px solid rgba(201, 163, 92, .38);
  box-shadow: 0 30px 90px rgba(0, 0, 0, .7), inset 0 0 80px rgba(201, 163, 92, .035);
  border-radius: 3px;
  scrollbar-width: thin;
  scrollbar-color: rgba(201, 163, 92, .35) transparent;
}
.overlay-panel::before, .overlay-panel::after {
  content: ""; position: absolute; width: 18px; height: 18px; border: 1px solid var(--gold); opacity: .5; pointer-events: none;
}
.overlay-panel::before { top: 7px; left: 7px; border-right: 0; border-bottom: 0; }
.overlay-panel::after { bottom: 7px; right: 7px; border-left: 0; border-top: 0; }
.overlay-panel h2 { font-size: clamp(28px, 4vw, 42px); letter-spacing: .08em; color: #eddfc3; margin-top: 2px; }
.overlay-sub { margin: 6px 0 18px; color: var(--bone-dim); font-size: 12px; letter-spacing: .03em; }

.levelup-panel { width: min(900px, 100%); text-align: center; }
.levelup-panel h2 span { color: var(--gold-bright); }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 20px 0 16px; }
.card {
  position: relative;
  text-align: left;
  padding: 16px 15px 14px;
  min-height: 158px;
  background: linear-gradient(165deg, rgba(35, 30, 27, .9), rgba(9, 10, 15, .95));
  border: 1px solid var(--line-soft);
  border-radius: 2px;
  cursor: pointer;
  transition: border-color .16s, transform .16s, box-shadow .16s;
  color: var(--bone);
  overflow: hidden;
}
.card::before { content: ""; position: absolute; inset: 0 0 auto; height: 2px; background: linear-gradient(90deg, transparent, var(--gold), transparent); opacity: .35; }
.card:hover { border-color: rgba(240, 210, 142, .65); transform: translateY(-3px); box-shadow: 0 12px 28px rgba(0, 0, 0, .4), 0 0 22px rgba(201, 163, 92, .08); }
.card .card-icon { width: 36px; height: 36px; margin-bottom: 10px; color: var(--gold); opacity: .9; }
.card .card-icon svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.card .card-name { font-family: var(--font-display); font-size: 17px; letter-spacing: .06em; color: #eadfc8; }
.card .card-desc { margin-top: 7px; font-size: 11px; line-height: 1.5; color: var(--bone-dim); }
.card .card-stack { position: absolute; top: 11px; right: 11px; font-family: var(--font-mono); font-size: 9px; color: var(--gold); opacity: .7; }
.card .card-tag { display: inline-block; margin-top: 10px; font-size: 8px; letter-spacing: .18em; text-transform: uppercase; color: var(--gold); border: 1px solid var(--line-soft); padding: 2px 6px; }
.levelup-foot { display: flex; justify-content: space-between; align-items: center; gap: 12px; border-top: 1px solid var(--line-soft); padding-top: 12px; }
.gold-inline { display: flex; align-items: center; gap: 6px; font-family: var(--font-mono); color: var(--gold-bright); font-size: 12px; }

/* inventory */
.inventory-panel { width: min(980px, 100%); }
.panel-head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 1px solid var(--line-soft); padding-bottom: 12px; margin-bottom: 16px; }
.inv-body { display: grid; grid-template-columns: 280px 1fr; gap: 20px; }
.paperdoll { display: flex; flex-direction: column; gap: 14px; }
.equip-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; }
.equip-cell {
  position: relative;
  height: 86px;
  border: 1px solid var(--line-soft);
  background: rgba(0, 0, 0, .3);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 4px;
  cursor: pointer;
  border-radius: 2px;
  padding: 6px;
}
.equip-cell:hover { border-color: var(--line); }
.equip-cell .slot-label { font-size: 8px; letter-spacing: .16em; text-transform: uppercase; color: var(--bone-dim); }
.equip-cell .item-icon { width: 44px; height: 44px; }
.equip-cell.empty .slot-glyph { width: 30px; height: 30px; opacity: .16; }
.stat-list { border-top: 1px solid var(--line-soft); padding-top: 10px; display: grid; grid-template-columns: 1fr 1fr; gap: 6px 12px; }
.stat-list div { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; color: var(--bone-dim); }
.stat-list div b { font-family: var(--font-mono); font-weight: 500; color: var(--bone); }
.stat-list div.hl b { color: var(--gold-bright); }
.bag { min-width: 0; }
.bag-head { display: flex; justify-content: space-between; font-size: 9px; letter-spacing: .2em; color: var(--bone-dim); margin-bottom: 7px; }
.bag-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  padding: 8px;
  background: rgba(0, 0, 0, .28);
  border: 1px solid var(--line-soft);
  min-height: 236px;
  align-content: start;
}
.item-cell {
  position: relative;
  aspect-ratio: 1;
  border: 1px solid rgba(255, 255, 255, .06);
  background: rgba(255, 255, 255, .018);
  display: grid; place-items: center;
  cursor: pointer;
  border-radius: 2px;
  padding: 0;
}
.item-cell:hover { border-color: rgba(240, 210, 142, .5); background: rgba(201, 163, 92, .05); }
.item-cell.empty { cursor: default; background: rgba(255, 255, 255, .008); border-color: rgba(255, 255, 255, .025); }
.item-cell .item-icon { width: 78%; height: 78%; }
.item-cell .new-dot { position: absolute; top: 3px; right: 3px; width: 5px; height: 5px; border-radius: 50%; background: var(--legendary); box-shadow: 0 0 6px var(--legendary); }
.bag-actions { display: flex; justify-content: space-between; gap: 10px; margin-top: 10px; }
.inv-hint { margin-top: 14px; padding-top: 10px; border-top: 1px solid var(--line-soft); font-size: 9px; letter-spacing: .08em; color: var(--bone-dim); text-align: center; }

/* item icons + rarity */
.item-icon { display: inline-grid; place-items: center; position: relative; flex: none; }
.item-icon svg { width: 100%; height: 100%; overflow: visible; }
.item-icon .icon-bg { fill: rgba(255, 255, 255, .03); }
.item-icon.rarity-common { color: var(--common); filter: drop-shadow(0 0 3px rgba(201, 196, 184, .18)); }
.item-icon.rarity-magic { color: var(--magic); filter: drop-shadow(0 0 4px rgba(110, 168, 255, .4)); }
.item-icon.rarity-rare { color: var(--rare); filter: drop-shadow(0 0 5px rgba(242, 207, 102, .45)); }
.item-icon.rarity-legendary { color: var(--legendary); filter: drop-shadow(0 0 7px rgba(255, 154, 60, .7)); }
.equip-cell.rarity-magic, .equip-slot.rarity-magic, .item-cell.rarity-magic { border-color: rgba(110, 168, 255, .55); }
.equip-cell.rarity-rare, .equip-slot.rarity-rare, .item-cell.rarity-rare { border-color: rgba(242, 207, 102, .55); }
.equip-cell.rarity-legendary, .equip-slot.rarity-legendary, .item-cell.rarity-legendary { border-color: rgba(255, 154, 60, .7); box-shadow: inset 0 0 14px rgba(255, 154, 60, .12); }
.equip-cell.rarity-common, .equip-slot.rarity-common, .item-cell.rarity-common { border-color: rgba(201, 196, 184, .4); }

/* tooltip */
.tooltip {
  position: fixed;
  z-index: 100;
  width: 280px;
  max-width: calc(100vw - 24px);
  padding: 12px 14px;
  background: linear-gradient(180deg, rgba(19, 17, 20, .98), rgba(6, 7, 10, .99));
  border: 1px solid var(--line);
  box-shadow: 0 16px 50px rgba(0, 0, 0, .7);
  border-radius: 2px;
  pointer-events: none;
  font-size: 11px;
  color: var(--bone);
}
.tooltip .tt-name { font-family: var(--font-display); font-size: 16px; letter-spacing: .03em; display: block; }
.tooltip .tt-base { display: block; margin-top: 2px; font-size: 9px; letter-spacing: .12em; text-transform: uppercase; color: var(--bone-dim); }
.tooltip .tt-sep { height: 1px; background: var(--line-soft); margin: 8px 0; }
.tooltip .tt-implicit { color: #e7dcc3; line-height: 1.6; }
.tooltip .tt-affix { color: #86b9ff; line-height: 1.65; }
.tooltip .tt-unique { margin-top: 7px; padding: 7px 8px; background: rgba(255, 154, 60, .07); border-left: 2px solid rgba(255, 154, 60, .6); }
.tooltip .tt-unique b { display: block; font-size: 8px; letter-spacing: .16em; text-transform: uppercase; color: var(--legendary); margin-bottom: 3px; }
.tooltip .tt-unique p { margin: 0; color: #ffcf9e; line-height: 1.5; font-style: italic; }
.tooltip .tt-compare { margin-top: 8px; border-top: 1px solid var(--line-soft); padding-top: 7px; display: grid; gap: 3px; }
.tooltip .tt-compare div { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; color: var(--bone-dim); }
.tooltip .tt-compare b { font-family: var(--font-mono); font-weight: 500; }
.tooltip .up { color: #79d18a; }
.tooltip .down { color: #e07171; }
.tooltip .tt-equipped { margin-top: 8px; font-size: 9px; color: var(--bone-dim); border-top: 1px dashed rgba(255, 255, 255, .1); padding-top: 6px; }

/* legendary */
.legendary-panel { width: min(520px, 100%); text-align: center; overflow: hidden; }
.legendary-panel .eyebrow { color: var(--legendary); }
.legendary-title {
  color: #ffd2a3 !important;
  text-shadow: 0 0 30px rgba(255, 154, 60, .4), 0 2px 0 #000;
  letter-spacing: .24em !important;
  font-size: clamp(22px, 3vw, 30px) !important;
}
.legendary-rays {
  position: absolute; inset: -40%;
  background: conic-gradient(from 0deg, transparent 0 8deg, rgba(255, 154, 60, .055) 8deg 10deg, transparent 10deg 20deg);
  animation: spin 26s linear infinite;
  pointer-events: none;
}
@keyframes spin { to { transform: rotate(360deg); } }
.legendary-card { position: relative; margin: 16px auto 18px; width: min(330px, 100%); }
.legendary-card .tooltip { position: static; width: 100%; display: block; box-shadow: 0 0 40px rgba(255, 154, 60, .12); border-color: rgba(255, 154, 60, .4); text-align: left; }
.legendary-actions { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; }

/* pause / end */
.pause-panel { width: min(430px, 100%); text-align: center; }
.pause-actions { display: grid; gap: 8px; margin: 22px 0 18px; }
.pause-actions .btn { width: 100%; }
.pause-controls { display: flex; justify-content: center; gap: 16px; flex-wrap: wrap; font-size: 9px; letter-spacing: .1em; text-transform: uppercase; color: var(--bone-dim); }
.pause-controls span { display: flex; align-items: center; gap: 5px; }
.pause-tip { margin: 18px 0 0; font-size: 10px; line-height: 1.6; color: var(--bone-dim); }
.end-panel { width: min(520px, 100%); text-align: center; }
.end-panel h2 { font-size: clamp(38px, 6vw, 58px); letter-spacing: .1em; }
.end-panel h2.win { color: #f2d98f; text-shadow: 0 0 40px rgba(201, 163, 92, .35); }
.end-panel h2.lose { color: #c74a4a; text-shadow: 0 0 40px rgba(180, 48, 48, .3); }
.end-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1px; background: var(--line-soft); border: 1px solid var(--line-soft); margin: 20px 0; }
.end-stats div { background: rgba(7, 8, 12, .75); padding: 10px; display: flex; justify-content: space-between; gap: 8px; font-size: 10px; color: var(--bone-dim); }
.end-stats b { font-family: var(--font-mono); color: var(--bone); font-weight: 500; }
.end-actions { display: flex; justify-content: center; gap: 8px; }

/* ---------- responsive ---------- */

@media (max-width: 760px) {
  .hud-top { grid-template-columns: 1fr auto; gap: 8px; }
  .hud-left { width: auto; max-width: 210px; padding: 7px 9px; }
  .level-badge { width: 31px; height: 31px; font-size: 14px; }
  .hud-stats { padding-left: 41px; gap: 8px; font-size: 8px; }
  .hud-stats span:nth-child(3) { display: none; }
  .hud-center { position: absolute; top: 4px; left: 50%; transform: translateX(-50%); }
  .timer { font-size: 25px; }
  .wave-label { font-size: 8px; letter-spacing: .16em; }
  .hud-right { grid-column: 2; }
  .currency { padding: 5px 8px; font-size: 10px; }
  .hud-buttons .icon-btn { width: 34px; height: 34px; }
  .equip-dock { display: none; }
  .hint { font-size: 8px; letter-spacing: .1em; bottom: max(14px, env(safe-area-inset-bottom)); }
  .toasts { bottom: max(44px, calc(env(safe-area-inset-bottom) + 38px)); }
  .cards { grid-template-columns: 1fr; gap: 8px; }
  .card { min-height: 0; padding: 12px; display: grid; grid-template-columns: 34px 1fr; grid-template-rows: auto auto; column-gap: 10px; }
  .card .card-icon { grid-row: 1 / span 2; margin: 0; width: 30px; height: 30px; align-self: center; }
  .card .card-name { font-size: 15px; }
  .card .card-desc { margin-top: 3px; font-size: 10px; }
  .card .card-stack { top: 9px; right: 9px; }
  .card .card-tag { display: none; }
  .inv-body { grid-template-columns: 1fr; gap: 14px; }
  .equip-grid { grid-template-columns: repeat(4, 1fr); }
  .equip-cell { height: 74px; }
  .stat-list { grid-template-columns: 1fr 1fr; }
  .bag-grid { grid-template-columns: repeat(4, 1fr); min-height: 0; }
  .menu-features { grid-template-columns: 1fr; }
  .menu-features div { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; padding: 9px 12px; }
  .menu-features b { margin: 0; }
  .menu-controls { gap: 12px; }
  .menu-footer { display: none; }
  .overlay { align-items: flex-start; padding-top: max(10px, env(safe-area-inset-top)); }
  .overlay-panel { max-height: calc(100dvh - 20px); }
  .levelup-foot { flex-direction: column; align-items: stretch; }
  .levelup-foot .gold-inline { justify-content: center; }
  .legendary-actions .btn { flex: 1; }
  .end-stats { grid-template-columns: 1fr; }
}

@media (max-width: 420px) {
  .menu-inner { padding: 18px 14px; }
  .logo { font-size: 58px; }
  .tagline { font-size: 12px; margin-bottom: 18px; }
  .menu-controls { margin: 16px 0 18px; }
  .hud-stats { display: none; }
  .hud-left { max-width: 168px; }
  .timer { font-size: 22px; }
  .hud-center { top: 2px; }
  .currency { gap: 4px; }
  .bag-grid { grid-template-columns: repeat(4, 1fr); }
}

@media (min-width: 761px) and (pointer: coarse) {
  .equip-dock { display: none; }
  .joystick { display: block; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; transition-duration: .001ms !important; }
}

// Static game data: rarities, item bases, affixes, uniques, boons and enemies.

export const RARITIES = {
