226: export function aggregateEquipment(equipment, boonStats = emptyStats()) {
227:   const stats = emptyStats();
228:   addStats(stats, boonStats);
229:   const flags = {
230:     pierce: 0, explodeOnKill: 0, bleedOnCrit: false, chainBonus: 0,
231:     burningGround: false, infinitePierce: false, evade: 0, thorns: 0,
232:     healOnKill: 0, burnOnHit: 0, goldHeal: 0
233:   };
234:   for (const item of Object.values(equipment)) {
235:     if (!item) continue;
236:     addStats(stats, item.stats);
237:     if (item.flags) {
238:       flags.pierce += item.flags.pierce || 0;
239:       flags.explodeOnKill = Math.max(flags.explodeOnKill, item.flags.explodeOnKill || 0);
240:       flags.bleedOnCrit = flags.bleedOnCrit || !!item.flags.bleedOnCrit;
241:       flags.chainBonus += item.flags.chainBonus || 0;
242:       flags.burningGround = flags.burningGround || !!item.flags.burningGround;
243:       flags.infinitePierce = flags.infinitePierce || !!item.flags.infinitePierce;
244:       flags.evade = Math.max(flags.evade, item.flags.evade || 0);
245:       flags.thorns += item.flags.thorns || 0;
246:       flags.healOnKill += item.flags.healOnKill || 0;
247:       flags.burnOnHit = Math.max(flags.burnOnHit, item.flags.burnOnHit || 0);
248:       flags.goldHeal += item.flags.goldHeal || 0;
249:     }
250:   }
251: 
252:   const weaponItem = equipment.weapon;
253:   const weapon = weaponItem ? {
254:     id: weaponItem.baseId,
255:     name: weaponItem.name,
256:     kind: weaponItem.kind,
257:     damage: weaponItem.damage,
258:     interval: weaponItem.interval,
259:     range: weaponItem.range,
260:     speed: weaponItem.speed,
261:     count: weaponItem.count || 1,
262:     pierce: (weaponItem.pierce || 0) + flags.pierce,
263:     radius: weaponItem.radius || 0,
264:     chains: (weaponItem.chains || 0) + flags.chainBonus,
265:     color: weaponItem.color || '#8fe7ff'
266:   } : {
267:     id: 'fists', name: 'Bare Hands', kind: 'bolt', damage: 4, interval: 1,
268:     range: 300, speed: 480, count: 1, pierce: 0, radius: 0, chains: 0, color: '#d9d1bd'
269:   };
270: 
271:   const maxLife = Math.max(20, 100 + stats.maxLife);
272:   const critChance = Math.max(0, Math.min(0.8, (5 + stats.critChance) / 100));
273:   const critMult = 1.5 + stats.critDamage / 100;
274:   const damageMult = 1 + stats.damagePct / 100;
275:   const interval = weapon.interval / (1 + stats.attackSpeedPct / 100);
276:   const weaponDamage = weapon.damage * damageMult;
277:   const shots = weapon.kind === 'knives' ? weapon.count : 1;
278:   const dps = weaponDamage * shots / Math.max(0.12, interval) * (1 + critChance * (critMult - 1));
279: 
280:   return {
281:     ...stats,
282:     maxLife,
283:     moveSpeed: 205 * (1 + stats.moveSpeedPct / 100),
284:     critChance,
285:     critMult,
286:     pickup: 88 + stats.pickup,
287:     damageMult,
288:     interval,
289:     weapon,
290:     weaponDamage,
291:     dps,
292:     flags
293:   };
294: }
