296: export function itemScore(item, boonStats) {
297:   const before = aggregateEquipment({}, boonStats);
298:   const after = aggregateEquipment({ [item.slot]: item }, boonStats);
299:   let score = (after.dps - before.dps) * 4;
300:   score += (after.maxLife - before.maxLife) * 0.35;
301:   score += (after.armor - before.armor) * 1.2;
302:   score += (after.moveSpeed - before.moveSpeed) * 0.6;
303:   score += (after.critChance - before.critChance) * 220;
304:   score += (after.pickup - before.pickup) * 0.15;
305:   score += (after.goldFind - before.goldFind) * 0.1;
306:   score += (after.magicFind - before.magicFind) * 0.12;
307:   score += (after.lifesteal - before.lifesteal) * 2.5;
308:   score += (after.projectiles - before.projectiles) * 12;
309:   return score;
310: }
