312: export function compareRows(item, equipment, boonStats) {
313:   const before = aggregateEquipment(equipment, boonStats);
314:   const after = aggregateEquipment({ ...equipment, [item.slot]: item }, boonStats);
315:   const rows = [];
316:   const push = (label, a, b, suffix = '', decimals = 0) => {
317:     const diff = b - a;
318:     if (Math.abs(diff) < (decimals ? 0.05 : 0.5)) return;
319:     const sign = diff > 0 ? '+' : '';
320:     rows.push({
321:       label,
322:       text: `${sign}${diff.toFixed(decimals)}${suffix}`,
323:       up: diff > 0
324:     });
325:   };
326:   push('DPS', before.dps, after.dps, '', 1);
327:   push('Max Life', before.maxLife, after.maxLife);
328:   push('Armor', before.armor, after.armor);
329:   push('Move Speed', before.moveSpeed, after.moveSpeed);
330:   push('Crit Chance', before.critChance * 100, after.critChance * 100, '%', 1);
331:   push('Attack Speed', before.attackSpeedPct, after.attackSpeedPct, '%');
332:   push('Damage', before.damagePct, after.damagePct, '%');
333:   push('Pickup', before.pickup, after.pickup);
334:   push('Gold Find', before.goldFind, after.goldFind, '%');
335:   push('Magic Find', before.magicFind, after.magicFind, '%');
336:   push('Life Steal', before.lifesteal, after.lifesteal, '%', 1);
337:   push('Projectiles', before.projectiles, after.projectiles);
338:   push('Area', before.areaPct, after.areaPct, '%');
339:   push('Regen', before.regen, after.regen, '/s', 1);
340:   return rows;
341: }
