const TAU = Math.PI * 2;
const ARENA = 1280;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function makeFloor() {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 512;
  const ctx = c.getContext('2d');
  let seed = 0x51ab1e;
  const rand = () => {
