      const y = row * size;
      const light = 8 + Math.floor(rand() * 5);
      ctx.fillStyle = `hsl(220 9% ${light}%)`;
      ctx.fillRect(x + 1, y + 1, size - 2, size - 2);
      ctx.strokeStyle = 'rgba(0,0,0,.55)';
      ctx.lineWidth = 2;
      ctx.strokeRect(x + 0.5, y + 0.5, size - 1, size - 1);
