async () => {
  const loot = await import('/js/loot.js');
  const { game } = window.__grimhoard;
  game.startRun();
  const priority = ['might','haste','multishot','carnage','precision','vitality','bulwark','fleet','luck','leech','regeneration','magnet','insight','avarice'];
  const agg = (eq) => loot.aggregateEquipment(eq, game.boonStats);
  const value = (d) => d.dps * 2.2 + d.maxLife * 0.5 + d.armor * 2.5 + d.moveSpeed * 0.9 + d.critChance * 220 + d.lifesteal * 3 + d.projectiles * 25 + d.regen * 6 + d.magicFind * 0.15 + d.goldFind * 0.05;
  const marks = new Set([30,60,120,180,240,300,330,360]);
  const log = [];
  let lastMark = -1;
  let equipped = 0;
  let picked = 0;
  const tryEquip = (item) => {
    if (!item) return false;
    const before = value(agg(game.equipment));
    const after = value(agg({ ...game.equipment, [item.slot]: item }));
    if (after > before + 0.5) {
      game.equipItem(item, { fromInventory: false });
      equipped++;
      return true;
    }
    return false;
  };
  for (let i = 0; i < 360*60 && (game.state === 'playing' || game.state === 'levelup' || game.state === 'legendary'); i++) {
    if (game.state === 'levelup') {
      const pick = game.choices.slice().sort((a,b)=>priority.indexOf(a.id)-priority.indexOf(b.id))[0];
      game.chooseBoon(pick.id);
      continue;
    }
    if (game.state === 'legendary') {
      const item = game.pendingLegendary;
      if (item) {
        const before = value(agg(game.equipment));
        const after = value(agg({ ...game.equipment, [item.slot]: item }));
        if (after > before) game.resolveLegendary('equip');
        else if (game.inventory.length < 24) game.resolveLegendary('take');
        else game.resolveLegendary('salvage');
      }
      continue;
    }
    const p = game.player;
    let tx = 0, ty = 0, found = false;
    // Nearest gear / pickup within 360
    let best = null, bestD = 360*360;
    for (const g of game.groundItems) {
      if (g.collected) continue;
      const d = (g.x-p.x)**2 + (g.y-p.y)**2;
      if (d < bestD) { bestD=d; best=g; }
    }
    if (best) { tx = best.x-p.x; ty = best.y-p.y; found=true; }
    if (!found) {
      let bp = null, bd = 230*230;
      for (const q of game.pickups) {
        const d = (q.x-p.x)**2 + (q.y-p.y)**2;
        if (d < bd) { bd=d; bp=q; }
      }
      if (bp) { tx = bp.x-p.x; ty = bp.y-p.y; found=true; }
    }
    if (!found) {
      // Kite gently around center to keep pickups flowing.
      const a = game.time * 0.25;
      tx = Math.cos(a)*200 - p.x*0.12;
      ty = Math.sin(a)*200 - p.y*0.12;
      found=true;
    }
    const len = Math.hypot(tx,ty) || 1;
    game.input.x = tx/len; game.input.y = ty/len;
    game.update(1/60);
    // Auto-pick gear at feet and equip if better.
    for (const g of [...game.groundItems]) {
      if (g.collected) continue;
      if ((g.x-p.x)**2 + (g.y-p.y)**2 < 46*46) {
        const before = game.groundItems.length;
        game.pickupGroundItem(g);
        if (game.state === 'legendary') break;
        if (game.groundItems.length < before) {
          picked++;
          tryEquip(g.item);
        }
      }
    }
    const sec = Math.floor(game.time);
    if (marks.has(sec) && sec !== lastMark) {
      lastMark = sec;
      log.push({t:sec,kills:game.kills,lvl:game.level,enemies:game.enemies.length,dps:+game.derived.dps.toFixed(1),hp:Math.round(game.player.hp),maxHp:Math.round(game.derived.maxLife),boss:game.boss?Math.round(game.boss.hp):null,bossMax:game.boss?Math.round(game.boss.maxHp):null,drops:game.itemsDropped,looted:game.itemsLooted,equipped});
    }
  }
  game.input.x=0; game.input.y=0;
  log.push({final:game.state,t:game.time,kills:game.kills,lvl:game.level,enemies:game.enemies.length,dps:+game.derived.dps.toFixed(1),bossDefeated:game.bossDefeated,drops:game.itemsDropped,looted:game.itemsLooted,equipped,inv:game.inventory.length,summary:game.runSummary()});
  return log;
}
