  score += (after.magicFind - before.magicFind) * 0.12;
  score += (after.lifesteal - before.lifesteal) * 2.5;
  score += (after.projectiles - before.projectiles) * 12;
  score += (after.regen - before.regen) * 5;
  score += (after.thorns - before.thorns) * 0.4;
  return score;
}

